#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using vi = vector<int>;
using mat = vector<vi>;

const int mod = 1000000007;

mat operator*(const mat& a, const mat& b) {
    assert(!a.empty() && !b.empty() && a[0].size() == b.size());

    mat res(a.size(), vi(b[0].size()));
    for (size_t i = 0; i < res.size(); ++i) {
        for (size_t j = 0; j < res[0].size(); ++j) {
            for (size_t k = 0; k < a[0].size(); ++k) {
                res[i][j] = (res[i][j] + (ll)a[i][k] * b[k][j]) % mod;
            }
        }
    }
    return res;
}

mat matrixPower(mat m, int n) {
    mat res(m.size(), vi(m.size()));
    for (size_t i = 0; i < m.size(); ++i) {
        res[i][i] = 1;
    }

    for (; n; n >>= 1) {
        if (n & 1) {
            res = res * m;
        }
        m = m * m;
    }
    return res;
}

int solve(int n) {
    mat M(50, vi(50));

    for (int i = 0; i < 5; ++i) {
        for (int j = 0; j < 5; ++j) {
            for (int k = 1; k < 5; ++k) {
                if (j == k || (j == 1 && k == 4) || (j == 4 && k == 1) ||
                    (j == 2 && k == 3) || (j == 3 && k == 2) ||
                    (i == 2 && j == 1 && k == 3) ||
                    (i == 3 && j == 1 && k == 2)) {
                    continue;
                }
                M[k * 5 + j][j * 5 + i] = 1;
            }
        }
    }

    for (int i = 0; i < 25; ++i) {
        M[i + 25][i] = 1;
        M[i + 25][i + 25] = 1;
    }

    M = matrixPower(M, n + 1);

    mat A(50, vi(25));
    for (int i = 0; i < 25; ++i) {
        A[i][i] = 1;
    }

    mat B = M * A;
    mat C(25, vi(1));
    C[0][0] = 1;
    mat D = B * C;

    ll res = 0;
    for (int i = 0; i < 25; ++i) {
        res += D[i + 25][0];
    }
    return res % mod;
}

int calc(int n) {
    int res = ((ll)solve(n) + solve((n + 1) / 2) - solve(2) + mod) % mod;
    if (res % 2) {
        res += mod;
    }
    return res / 2;
}

